import{_ as e,o as a,c as l,an as i}from"./chunks/framework.8hZZ_P8L.js";const y=JSON.parse('{"title":"Capabilities matrix","description":"","frontmatter":{},"headers":[],"relativePath":"capabilities.md","filePath":"capabilities.md","lastUpdated":null}'),r={name:"capabilities.md"};function d(n,t,s,o,c,g){return a(),l("div",null,[...t[0]||(t[0]=[i(`<h1 id="Capabilities-matrix" tabindex="-1">Capabilities matrix <a class="header-anchor" href="#Capabilities-matrix" aria-label="Permalink to &quot;Capabilities matrix {#Capabilities-matrix}&quot;">​</a></h1><p>These are the capabilities of the <strong>mature LBM core</strong> within Kraken&#39;s broader method-agnostic platform. For how LBM fits the platform — and what is shipped versus on the roadmap across methods — see the <a href="./architecture">architecture overview</a>.</p><p>This page is the single-source-of-truth for <strong>what the LBM core can do today</strong>, what is partially implemented, and what is out of scope. Rows were last checked against the code on <code>dev/platform</code> in November 2026 (after v0.5.1). Every entry links to the theory page that derives it, the example that exercises it, and the API or .krk reference that documents how to call it.</p><p>A ✓ means the feature runs and a test in <code>test/</code> exercises it. Rows marked <strong>code present, later release</strong> exist in the codebase (and in some cases are fully tested) but are not part of the validated surface.</p><p>Legend: ✓ = works and tested · ~ = implemented, partial validation · — = not applicable · ✗ = not yet</p><hr><h2 id="1.-Core-LBM" tabindex="-1">1. Core LBM <a class="header-anchor" href="#1.-Core-LBM" aria-label="Permalink to &quot;1. Core LBM {#1.-Core-LBM}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Capability</th><th style="text-align:center;">2D</th><th style="text-align:center;">3D</th><th style="text-align:center;">GPU</th><th style="text-align:center;">.krk</th><th style="text-align:center;">Theory</th><th style="text-align:center;">Example</th><th style="text-align:center;">API</th></tr></thead><tbody><tr><td style="text-align:right;">D2Q9 / D3Q19 lattice</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"><a href="./theory/01_lbm_fundamentals">01</a>, <a href="./theory/02_d2q9_lattice">02</a>, <a href="./theory/06_from_2d_to_3d">06</a></td><td style="text-align:center;"><a href="./examples/01_poiseuille_2d">Poiseuille 2D</a>, <a href="./examples/04_cavity_2d">Cavity (2D &amp; 3D)</a></td><td style="text-align:center;"><a href="./api/lattice">lattice</a></td></tr><tr><td style="text-align:right;">BGK collision</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"><a href="./theory/03_bgk_collision">03</a></td><td style="text-align:center;"><a href="./examples/04_cavity_2d">Cavity 2D</a></td><td style="text-align:center;"><a href="./api/collision">collision</a></td></tr><tr><td style="text-align:right;">MRT collision</td><td style="text-align:center;">✓</td><td style="text-align:center;">✗</td><td style="text-align:center;">✓</td><td style="text-align:center;">~ EHD only (<code>ns_scheme = mrt</code>)</td><td style="text-align:center;"><a href="./theory/12_mrt">12</a></td><td style="text-align:center;">—</td><td style="text-align:center;"><a href="./api/collision">collision</a></td></tr><tr><td style="text-align:right;">TRT collision</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">~ 2D: <code>Physics collision = trt</code>, Newtonian, no body force, wall boundaries only</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;"><code>fused_trt_libb_v2_step_3d!</code> (3D cut-link driver, Julia API)</td></tr><tr><td style="text-align:right;">Streaming (periodic/wall)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"><a href="./theory/04_streaming">04</a></td><td style="text-align:center;"><a href="./examples/02_couette_2d">Couette</a></td><td style="text-align:center;"><a href="./api/streaming">streaming</a></td></tr><tr><td style="text-align:right;">Macroscopic recovery (ρ, u)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:center;"><a href="./theory/01_lbm_fundamentals">01</a></td><td style="text-align:center;">—</td><td style="text-align:center;"><a href="./api/macroscopic">macroscopic</a></td></tr><tr><td style="text-align:right;">Body force (Guo forcing)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"><a href="./theory/07_body_forces">07</a></td><td style="text-align:center;"><a href="./examples/01_poiseuille_2d">Poiseuille 2D</a></td><td style="text-align:center;"><a href="./api/collision">collision</a></td></tr><tr><td style="text-align:right;">Axisymmetric (z, r)</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;"><a href="./theory/09_axisymmetric">09</a></td><td style="text-align:center;"><a href="./examples/09_hagen_poiseuille">Hagen–Poiseuille</a></td><td style="text-align:center;"><a href="./api/drivers">drivers</a></td></tr></tbody></table><p><strong>Limitations:</strong> MRT is D2Q9 only, and a plain <code>.krk</code> file cannot select it (only the EHD solver reads <code>ns_scheme = mrt</code>). TRT in 3D exists for the cut-link obstacle and sphere drivers and is called from Julia, not selected from <code>.krk</code>. D3Q27 is not implemented.</p><h2 id="2.-Boundary-conditions" tabindex="-1">2. Boundary conditions <a class="header-anchor" href="#2.-Boundary-conditions" aria-label="Permalink to &quot;2. Boundary conditions {#2.-Boundary-conditions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">BC type</th><th style="text-align:center;">2D</th><th style="text-align:center;">3D</th><th style="text-align:center;">Spatial f(x,y,z)</th><th style="text-align:center;">Time f(t)</th><th style="text-align:right;">.krk syntax</th></tr></thead><tbody><tr><td style="text-align:right;">Wall (bounce-back)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;"><code>Boundary north wall</code></td></tr><tr><td style="text-align:right;">Velocity (Zou-He)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:right;"><code>Boundary west velocity(ux=4*U*y*(H-y)/H^2)</code></td></tr><tr><td style="text-align:right;">Pressure/density outlet</td><td style="text-align:center;">✓ (west, east)</td><td style="text-align:center;">~ (east and top faces only; one no-NaN smoke test; see issue #20)</td><td style="text-align:center;">~</td><td style="text-align:center;">✓</td><td style="text-align:right;"><code>Boundary east pressure(rho=1.0)</code></td></tr><tr><td style="text-align:right;">Periodic</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;"><code>Boundary x periodic</code></td></tr><tr><td style="text-align:right;">Fixed temperature (Dirichlet)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✗</td><td style="text-align:center;">✗</td><td style="text-align:right;"><code>Boundary west wall(T=1.0)</code>; from <code>.krk</code>, read only by <code>heat_conduction</code> cases (see the note below)</td></tr><tr><td style="text-align:right;">Adiabatic (zero-flux)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">default when no <code>T=</code> specified</td></tr><tr><td style="text-align:right;">Outflow / Neumann / symmetry</td><td style="text-align:center;">~</td><td style="text-align:center;">~</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:right;">recognized, partial</td></tr></tbody></table><ul><li><p>Theory: <a href="./theory/05_boundary_conditions">05 BCs</a>, <a href="./theory/19_spatial_bcs">19 spatial BCs</a></p></li><li><p>.krk: <a href="./krk/bc_types">BC types</a>, <a href="./krk/expressions">Expressions</a></p></li><li><p>Expression whitelist: arithmetic, <code>sin/cos/tan/exp/log/sqrt/abs/clamp</code>, variables <code>x, y, z, t, Lx, Ly, Lz, Nx, Ny, Nz, dx, dy, dz</code> + <code>Define</code>d vars.</p></li></ul><p><strong>Limitations:</strong> thermal BCs are scalar only (no <code>T = f(x,y,t)</code>). In a <code>.krk</code> file the <code>T = ...</code> values on <code>Boundary</code> lines are used by <code>heat_conduction</code> cases only (one opposing pair of faces). The <code>natural_convection</code> and <code>rayleigh_benard</code> cases ignore them and use the driver values (hot = 1, cold = 0; hot west and cold east for natural convection, hot south and cold north for Rayleigh-Bénard). Outflow/Neumann/symmetry are recognized by the parser but kernels are minimal — use with caution.</p><h2 id="3.-Thermal" tabindex="-1">3. Thermal <a class="header-anchor" href="#3.-Thermal" aria-label="Permalink to &quot;3. Thermal {#3.-Thermal}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Capability</th><th style="text-align:center;">2D</th><th style="text-align:center;">3D</th><th style="text-align:center;">Refined</th><th style="text-align:center;">GPU</th><th style="text-align:center;">.krk</th><th style="text-align:right;">Theory / Example</th></tr></thead><tbody><tr><td style="text-align:right;">Passive scalar transport (DDF)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">in development</td><td style="text-align:center;">✓</td><td style="text-align:center;"><code>Module thermal</code></td><td style="text-align:right;"><a href="./theory/08_thermal_ddf">08 thermal DDF</a></td></tr><tr><td style="text-align:right;">Boussinesq buoyancy</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">in development</td><td style="text-align:center;">✓</td><td style="text-align:center;">built into the <code>natural_convection</code> and <code>rayleigh_benard</code> cases, chosen by the <code>Simulation</code> name (not enabled by the BCs); Ra and Pr come from <code>Physics</code>/<code>Setup</code></td><td style="text-align:right;"><a href="./examples/08_rayleigh_benard">Rayleigh-Bénard</a></td></tr><tr><td style="text-align:right;">Heat conduction (pure)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./examples/07_heat_conduction">Heat conduction</a></td></tr><tr><td style="text-align:right;">Natural convection (cavity)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">in development</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:right;">driver <code>run_natural_convection_2d/3d</code></td></tr><tr><td style="text-align:right;">Natural convection, generalised Newtonian (power law, Carreau-Yasuda…)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✗</td><td style="text-align:center;">✗</td><td style="text-align:center;">✓ (one A100, Float64)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./users/benchmarks/gnf-natural-convection">GNF natural convection</a>; driver <code>run_natural_convection_gnf_2d</code></td></tr><tr><td style="text-align:right;">ν(T) Arrhenius (kernel)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✗</td><td style="text-align:center;">✗</td><td style="text-align:center;">✓</td><td style="text-align:center;">✗</td><td style="text-align:right;">code: <code>collide_boussinesq_vt_2d!</code></td></tr><tr><td style="text-align:right;">ν(T) modified Arrhenius (Rc)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✗</td><td style="text-align:center;">✗</td><td style="text-align:center;">✓</td><td style="text-align:center;">✗</td><td style="text-align:right;">driver via <code>Rc</code> keyword</td></tr><tr><td style="text-align:right;">α(T), κ(T) variable diffusivity</td><td style="text-align:center;">✗</td><td style="text-align:center;">✗</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">✗</td><td style="text-align:right;">not implemented</td></tr><tr><td style="text-align:right;">Validation vs De Vahl Davis (Ra=1e3)</td><td style="text-align:center;">✓ +0.13 % (N = 64)</td><td style="text-align:center;">—</td><td style="text-align:center;">in development</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:right;">hot-wall Nu₀ = 1.117 ref</td></tr><tr><td style="text-align:right;">Validation vs Fusegi (3D Ra=1e3)</td><td style="text-align:center;">—</td><td style="text-align:center;">~ 5%</td><td style="text-align:center;">in development</td><td style="text-align:center;">✓</td><td style="text-align:center;">—</td><td style="text-align:right;">Nu = 1.085 ref</td></tr></tbody></table><p><strong>Limitations:</strong></p><ul><li><p>ν(T) is wired at the <strong>driver</strong> level (<code>run_natural_convection_2d(; Rc=5)</code>) but <strong>not yet dispatched from .krk</strong>. Adding <code>Rc = 5</code> in <code>Physics {}</code> does not activate the variable-viscosity kernel. Workaround: call the Julia API directly.</p></li><li><p>No custom <code>ν(x, y, z, t, γ̇, T)</code> user-defined function inlined into kernels — this requires a parser extension (not implemented).</p></li><li><p>Thermal BCs are scalar only; <code>T = sin(π*y)*t/T_max</code> is not supported yet.</p></li></ul><h2 id="4.-Grid-refinement-under-development" tabindex="-1">4. Grid refinement (under development) <a class="header-anchor" href="#4.-Grid-refinement-under-development" aria-label="Permalink to &quot;4. Grid refinement (under development) {#4.-Grid-refinement-under-development}&quot;">​</a></h2><p>Grid refinement (patch and conservative AMR) is under development and not validated; it is not part of the supported feature set. No refinement capability is listed as working here. The code and its tests remain in the repository for development purposes. The reasons it is not validated are given in <a href="./theory/10_limitations">Limitations</a>. The <code>.krk</code> <code>Refine</code> keyword is parsed but is under development and not validated; see <a href="./krk/directives">directives</a>.</p><h2 id="5.-Geometry-and-obstacles" tabindex="-1">5. Geometry and obstacles <a class="header-anchor" href="#5.-Geometry-and-obstacles" aria-label="Permalink to &quot;5. Geometry and obstacles {#5.-Geometry-and-obstacles}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Capability</th><th style="text-align:center;">Status</th><th style="text-align:right;">.krk syntax</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;">Implicit condition (circle, box, sphere)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><code>Obstacle cyl { (x-cx)^2 + (y-cy)^2 &lt;= R^2 }</code></td><td style="text-align:right;">any boolean expression</td></tr><tr><td style="text-align:right;">STL import (binary + ASCII)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><code>Obstacle body stl(file=&quot;geom.stl&quot;, scale=0.5)</code></td><td style="text-align:right;">auto-detect format</td></tr><tr><td style="text-align:right;">3D voxelization (Möller–Trumbore ray casting)</td><td style="text-align:center;">✓</td><td style="text-align:right;">—</td><td style="text-align:right;">requires watertight mesh</td></tr><tr><td style="text-align:right;">2D voxelization (slice at z_slice)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><code>stl(file=..., z_slice=0.0)</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;">Named primitives <code>circle()</code>, <code>box()</code>, <code>sphere()</code></td><td style="text-align:center;">✗</td><td style="text-align:right;">not implemented</td><td style="text-align:right;">ergonomic sugar for common shapes</td></tr><tr><td style="text-align:right;">Multiple obstacles</td><td style="text-align:center;">✓</td><td style="text-align:right;">repeat <code>Obstacle</code> block</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;">Fluid region (inverse logic)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><code>Fluid inside { x &lt; L/2 }</code></td><td style="text-align:right;">—</td></tr></tbody></table><ul><li><p>Theory: — (voxelization is implementation detail, not LBM theory)</p></li><li><p>API: <a href="./api/io">io</a> — <code>read_stl</code>, <code>voxelize_2d</code>, <code>voxelize_3d</code></p></li></ul><p><strong>Limitation:</strong> no named primitives yet. Users must spell out <code>(x-cx)^2 + (y-cy)^2 &lt;= R^2</code>. A possible syntax, not implemented:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Obstacle cyl circle(center=[0.5, 0.5], radius=0.1)</span></span>
<span class="line"><span>Obstacle box rectangle(xmin=0.2, xmax=0.8, ymin=0.3, ymax=0.7)</span></span>
<span class="line"><span>Obstacle sph sphere(center=[0.5, 0.5, 0.5], radius=0.1)</span></span></code></pre></div><h2 id="6.-Sanity-checks-parameter-validation" tabindex="-1">6. Sanity checks (parameter validation) <a class="header-anchor" href="#6.-Sanity-checks-parameter-validation" aria-label="Permalink to &quot;6. Sanity checks (parameter validation) {#6.-Sanity-checks-parameter-validation}&quot;">​</a></h2><p>Running <code>sanity_check(setup)</code> — and the check that <code>run_simulation</code> does automatically — covers the following:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Check</th><th style="text-align:right;">Level</th><th style="text-align:right;">What it verifies</th></tr></thead><tbody><tr><td style="text-align:right;">Relaxation τ = 3ν + 0.5</td><td style="text-align:right;">error/warn</td><td style="text-align:right;">τ &lt; 0.5 unstable; τ &lt; 0.51 marginal; τ &gt; 10 over-diffusive</td></tr><tr><td style="text-align:right;">Compressibility</td><td style="text-align:right;">error/warn</td><td style="text-align:right;">U_ref (Ma = U/c_s); Ma &gt; 0.1 flags compressibility error</td></tr><tr><td style="text-align:right;">Spatial resolution</td><td style="text-align:right;">warn</td><td style="text-align:right;">N &lt; 10, N/Re &lt; 1 (boundary layer under-resolved)</td></tr><tr><td style="text-align:right;">Thermal τ_α = 3α + 0.5</td><td style="text-align:right;">error/warn</td><td style="text-align:right;">same bounds as flow τ</td></tr><tr><td style="text-align:right;">Prandtl number</td><td style="text-align:right;">warn</td><td style="text-align:right;">Pr &lt; 0.1 or &gt; 10 extreme for SRT thermal</td></tr><tr><td style="text-align:right;">Rheology τ_min</td><td style="text-align:right;">warn</td><td style="text-align:right;">from <code>nu_min</code> in GNF models</td></tr><tr><td style="text-align:right;">Fine-grid checks (refinement)</td><td style="text-align:right;">warn</td><td style="text-align:right;">under development, not validated</td></tr><tr><td style="text-align:right;">Two-phase density/viscosity ratio</td><td style="text-align:right;">warn</td><td style="text-align:right;">code present, not part of the validated surface</td></tr></tbody></table><ul><li><p>.krk: <a href="./krk/sanity">Sanity checks</a></p></li><li><p>Parameter summary is printed at run-time with 2D/3D tag.</p></li></ul><p><strong>Limitations / planned:</strong></p><ul><li><p>No Ra-vs-N thermal BL resolution check (planned — ~ Ra^{1/4} minimum N).</p></li><li><p>No CFL check for prescribed-velocity advection.</p></li><li><p>Custom user checks not yet exposed in .krk.</p></li></ul><h2 id="7.-KRK-DSL" tabindex="-1">7. KRK DSL <a class="header-anchor" href="#7.-KRK-DSL" aria-label="Permalink to &quot;7. KRK DSL {#7.-KRK-DSL}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Feature</th><th style="text-align:center;">Status</th><th style="text-align:right;">Reference</th></tr></thead><tbody><tr><td style="text-align:right;"><code>.krk</code> extension + VSCode highlighting</td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./krk/overview">overview</a></td></tr><tr><td style="text-align:right;">Core directives (Simulation, Domain, Physics, Run, Output)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./krk/directives">directives</a></td></tr><tr><td style="text-align:right;">Boundary / Initial / Obstacle / Fluid / Velocity blocks</td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./krk/directives">directives</a></td></tr><tr><td style="text-align:right;">Modules: <code>thermal</code>, <code>axisymmetric</code></td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./krk/modules">modules</a></td></tr><tr><td style="text-align:right;">Rheology block (GNF + VE parsing)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./krk/directives">directives</a></td></tr><tr><td style="text-align:right;"><code>Refine</code> block</td><td style="text-align:center;">in development</td><td style="text-align:right;"><a href="./krk/directives">directives</a></td></tr><tr><td style="text-align:right;">Define user variables</td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./krk/expressions">expressions</a></td></tr><tr><td style="text-align:right;">Expressions (math + <code>x, y, z, t</code>)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./krk/expressions">expressions</a></td></tr><tr><td style="text-align:right;"><strong>Greek letters</strong> (ν/nu, ρ/rho, σ/sigma, τ/tau …)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./krk/aliases">aliases</a></td></tr><tr><td style="text-align:right;">ASCII aliases (<code>nu</code> → <code>ν</code>)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./krk/aliases">aliases</a></td></tr><tr><td style="text-align:right;"><strong>CLI wrapper</strong> (<code>kraken run sim.krk</code>)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><code>bin/kraken</code> (also <code>kraken info sim.krk</code>)</td></tr><tr><td style="text-align:right;"><code>Backend &lt;cpu|cuda|metal&gt;</code> directive</td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./krk/directives">directives</a></td></tr><tr><td style="text-align:right;">Preset templates (cavity_2d, etc.)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./krk/presets">presets</a></td></tr><tr><td style="text-align:right;">Setup helpers (<code>Setup reynolds = 100</code>)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./krk/helpers">helpers</a></td></tr><tr><td style="text-align:right;">Sweep (parametric studies)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><a href="./krk/directives">directives</a></td></tr></tbody></table><p><strong>Limitations:</strong></p><ul><li><p>No <code>include</code> directive for reusable .krk fragments.</p></li><li><p>No conditional blocks (<code>if Re &gt; 100 { ... }</code>).</p></li><li><p>Sweeps are Cartesian product; no Latin hypercube.</p></li></ul><h2 id="8.-GPU-support" tabindex="-1">8. GPU support <a class="header-anchor" href="#8.-GPU-support" aria-label="Permalink to &quot;8. GPU support {#8.-GPU-support}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Backend</th><th style="text-align:center;">Status</th><th style="text-align:right;">File type</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;">CPU (KernelAbstractions)</td><td style="text-align:center;">✓</td><td style="text-align:right;">Float32/Float64</td><td style="text-align:right;">reference</td></tr><tr><td style="text-align:right;">Metal (Apple Silicon)</td><td style="text-align:center;">~</td><td style="text-align:right;">Float32 recommended</td><td style="text-align:right;">run on an M3 Max (throughput CSV only); no Metal test in the suite</td></tr><tr><td style="text-align:right;">CUDA (NVIDIA)</td><td style="text-align:center;">~</td><td style="text-align:right;">Float32/Float64</td><td style="text-align:right;">run on A100 and H100 on the QUT Aqua cluster (certification CSV for A100 only); CUDA tests in the suite self-skip without a GPU, and CI has no GPU runner</td></tr><tr><td style="text-align:right;">ROCm (AMD)</td><td style="text-align:center;">✗</td><td style="text-align:right;">—</td><td style="text-align:right;">KA supports it, not tested</td></tr><tr><td style="text-align:right;">oneAPI (Intel)</td><td style="text-align:center;">✗</td><td style="text-align:right;">—</td><td style="text-align:right;">—</td></tr></tbody></table><ul><li><p>All kernels use <code>KernelAbstractions.@kernel</code> → single source, multi-backend.</p></li><li><p><strong>Fix a82957c:</strong> <code>unsafe_trunc</code> instead of <code>trunc(Int, ...)</code> in all refinement and dualgrid kernels (required for Metal; allocated on GPU).</p></li></ul><p><strong>Performance reference:</strong> the one committed CUDA throughput measurement is 3461 MLUPS (BGK D2Q9, Float64, <code>N = 2048</code>, A100-40GB), 0.32 of that GPU&#39;s bandwidth ceiling (<code>benchmarks/results/certification_a100.csv</code>; see <a href="./users/benchmarks/gpu-certification">GPU certification</a>). No H100 LBM throughput number is published. Apple M3 Max throughput is in <a href="./benchmarks/performance">Performance</a>.</p><h2 id="9.-Rheology" tabindex="-1">9. Rheology <a class="header-anchor" href="#9.-Rheology" aria-label="Permalink to &quot;9. Rheology {#9.-Rheology}&quot;">​</a></h2><p>Beyond Oldroyd-B (the validated viscoelastic model), the models below are <strong>implemented in code</strong>; their validation level differs from row to row. The &quot;GPU&quot; column means the collision kernel is KernelAbstractions-based, which does not imply a GPU test. &quot;Thermal coupling&quot; is the shift of the model parameters with temperature (<code>thermal_shift_factor</code>); it is implemented for the generalised-Newtonian models only, and only one driver calls the thermal rheology kernel (<code>collide_rheology_thermal_2d!</code>, via <code>run_natural_convection_gnf_2d</code>, 2D natural convection, reachable from <code>.krk</code>).</p><table tabindex="0"><thead><tr><th style="text-align:right;">Model</th><th style="text-align:center;">2D</th><th style="text-align:center;">3D</th><th style="text-align:center;">GPU</th><th style="text-align:center;">Thermal coupling</th></tr></thead><tbody><tr><td style="text-align:right;">Newtonian</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">— (constant viscosity; <code>n = 1</code> power law in the GNF thermal driver)</td></tr><tr><td style="text-align:right;">Power-law</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓ (isothermal; Julia API)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓ 2D natural convection, <code>run_natural_convection_gnf_2d</code></td></tr><tr><td style="text-align:right;">Carreau-Yasuda</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓ (isothermal; Julia API)</td><td style="text-align:center;">✓</td><td style="text-align:center;">accepted by <code>run_natural_convection_gnf_2d</code>; only a run-through test, no reference comparison</td></tr><tr><td style="text-align:right;">Carreau-Yasuda steady adjoint (<code>gnf_steady_gradient</code>; tests <code>test/ad/gnf_adjoint_test.jl</code>, <code>test/ad/gnf_adjoint_enzyme_test.jl</code>; one A100, Float64, run archived under <code>benchmarks/validation/gnf_adjoint/results/</code>)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✗</td><td style="text-align:center;">✓ (one A100)</td><td style="text-align:center;">—</td></tr><tr><td style="text-align:right;">Cross</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓ (isothermal; Julia API)</td><td style="text-align:center;">✓</td><td style="text-align:center;">accepted by <code>run_natural_convection_gnf_2d</code>, not tested there</td></tr><tr><td style="text-align:right;">Bingham (Papanastasiou)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✗</td><td style="text-align:center;">✓</td><td style="text-align:center;">accepted by <code>run_natural_convection_gnf_2d</code>, not tested there</td></tr><tr><td style="text-align:right;">Herschel–Bulkley</td><td style="text-align:center;">✓</td><td style="text-align:center;">✗</td><td style="text-align:center;">✓</td><td style="text-align:center;">accepted by <code>run_natural_convection_gnf_2d</code>, not tested there</td></tr><tr><td style="text-align:right;">Oldroyd-B (log-conf)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓ (FVFD)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✗</td></tr><tr><td style="text-align:right;">FENE-P</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓ (FVFD)</td><td style="text-align:center;">✓</td><td style="text-align:center;">✗</td></tr><tr><td style="text-align:right;">Saramito (EVP)</td><td style="text-align:center;">model type and <code>.krk</code> parsing only</td><td style="text-align:center;">✗</td><td style="text-align:center;">✗ (no solver kernel)</td><td style="text-align:center;">✗</td></tr></tbody></table><p><strong>3D generalised-Newtonian (Julia API only).</strong> <code>run_gnf_channel_3d</code> (D3Q19 TRT, LI-BB walls, Guo forcing; Power-law, Carreau-Yasuda, Cross) is isothermal, has no <code>.krk</code> keyword yet, and is verified against an exact planar-channel solution on CPU Float64 (<code>test/analytical/gnf3d_channel_order.jl</code>, observed order 1.93 to 2.00) and on an A100 (Float64, N = 32 to 256, order 1.95 to 2.001, archived sweep, not a test). With a constant viscosity it equals the Newtonian step (<code>test/analytical/gnf3d_parity.jl</code>); the strain-rate estimate is in <code>test/analytical/gnf3d_strain_rate.jl</code>. Bingham and Herschel-Bulkley have no 3D path. See <a href="./users/benchmarks/gnf3d-channel-convergence">3D GNF channel</a>.</p><p><strong>3D viscoelastic (since v0.5.0).</strong> Oldroyd-B, FENE-P, Giesekus and PTT (linear and exponential) run in 3D in log-conformation form on the FVFD path only (<code>run_viscoelastic_fvfd_poiseuille_3d</code>, <code>run_viscoelastic_fvfd_extensional_3d</code>). Oldroyd-B is validated against analytic solutions and RheoTool on periodic Poiseuille and, with the velocity imposed, planar extension. The coupled planar-extension mode is not validated: two known defects of its driver (a velocity read-back after collision, issue #68, and Zou-He face rebuilds that skip the periodic z planes, issue #69) are open and recorded as broken tests. FENE-P, Giesekus and PTT against their closed-form simple-shear fixed points (FENE-P also against its transcendental planar-extension fixed point), and in the coupled flows through their Oldroyd-B limit and qualitative trends — see <a href="./users/benchmarks/ve-constitutive-models">Viscoelastic constitutive models</a>. The 3D LBM-CDE drivers (sphere, Couette, Poiseuille) accept Oldroyd-B only, in direct conformation form, and the sphere driver is not validated against a viscoelastic reference. The 3D viscoelastic tests run on CPU; the GPU and thermal-coupling columns above refer to 2D.</p><p>Effective viscosity dispatches at compile-time (zero-cost abstraction via Julia&#39;s JIT). See <code>src/rheology/</code> (models, viscosity, strain_rate).</p><h2 id="10.-Output-and-diagnostics" tabindex="-1">10. Output and diagnostics <a class="header-anchor" href="#10.-Output-and-diagnostics" aria-label="Permalink to &quot;10. Output and diagnostics {#10.-Output-and-diagnostics}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Output</th><th style="text-align:center;">Status</th><th style="text-align:right;">.krk syntax</th></tr></thead><tbody><tr><td style="text-align:right;">VTK (+ PVD time series)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><code>Output vtk every 1000 [rho, ux, uy]</code></td></tr><tr><td style="text-align:right;">PNG snapshots (CairoMakie)</td><td style="text-align:center;">✓</td><td style="text-align:right;"><code>Output png every 500 [uy]</code></td></tr><tr><td style="text-align:right;">GIF animations</td><td style="text-align:center;">✓</td><td style="text-align:right;"><code>Output gif every 100 [ux] fps=15</code></td></tr><tr><td style="text-align:right;">Diagnostics CSV</td><td style="text-align:center;">✓</td><td style="text-align:right;"><code>Diagnostics every 100 [step, drag, lift]</code></td></tr><tr><td style="text-align:right;">ParaView-ready layout</td><td style="text-align:center;">✓</td><td style="text-align:right;">— (VTK pvd files)</td></tr></tbody></table><ul><li><p>API: <a href="./api/io">io</a>, <a href="./api/postprocess">postprocess</a></p></li><li><p>Helper: <code>open_paraview(result)</code> opens the latest output in ParaView.</p></li></ul><hr><h2 id="Not-part-of-the-validated-surface" tabindex="-1">Not part of the validated surface <a class="header-anchor" href="#Not-part-of-the-validated-surface" aria-label="Permalink to &quot;Not part of the validated surface {#Not-part-of-the-validated-surface}&quot;">​</a></h2><p>These features exist in the codebase (tests often pass) but are not documented as validated:</p><ul><li><p><strong>Multiphase (VOF + PLIC)</strong>: <code>src/kernels/vof_2d.jl</code>, <code>src/kernels/pressure_vof_2d.jl</code></p></li><li><p><strong>Phase-field (Allen-Cahn)</strong>: <code>src/kernels/phasefield_2d.jl</code></p></li><li><p><strong>Shan–Chen spinodal</strong>: <code>src/drivers/multiphase.jl</code></p></li><li><p><strong>Species transport</strong>: <code>src/kernels/species_2d.jl</code></p></li><li><p><strong>Viscoelastic cylinder driver</strong>: <code>src/drivers/viscoelastic.jl</code></p></li><li><p><strong>3D generalised-Newtonian rheology</strong>: kernels are 2D only (3D viscoelastic: see §9)</p></li><li><p><strong>3D MRT</strong>: not implemented (D3Q19 BGK and TRT only)</p></li><li><p><strong>Left-out test modules</strong>: conservative-tree AMR, multiblock, SLBM and Gmsh drag have test files that the default suite does not run; set <code>KRAKEN_TEST_EXPERIMENTAL=1</code> to run them.</p></li></ul><hr><h2 id="Quick-decision-helper" tabindex="-1">Quick decision helper <a class="header-anchor" href="#Quick-decision-helper" aria-label="Permalink to &quot;Quick decision helper {#Quick-decision-helper}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">I want to…</th><th style="text-align:right;">I need…</th></tr></thead><tbody><tr><td style="text-align:right;">lid-driven cavity 2D</td><td style="text-align:right;">BGK + wall BCs + velocity BC. <a href="./examples/04_cavity_2d">Example</a></td></tr><tr><td style="text-align:right;">flow past a cylinder</td><td style="text-align:right;">BGK + inlet parabolic BC + obstacle (<code>Obstacle { ... }</code>). <a href="./examples/06_cylinder_2d">Example</a></td></tr><tr><td style="text-align:right;">natural convection in a cavity</td><td style="text-align:right;"><code>Module thermal</code> + two <code>wall(T=...)</code> BCs. <a href="./examples/08_rayleigh_benard">Example</a></td></tr><tr><td style="text-align:right;">refine near a wall</td><td style="text-align:right;">not available: grid refinement is under development and not validated</td></tr><tr><td style="text-align:right;">run on H100/A100</td><td style="text-align:right;"><code>Backend cuda</code> in the <code>.krk</code> file, or <code>run_simulation(...; backend=CUDABackend())</code></td></tr><tr><td style="text-align:right;">vary the viscosity with temperature</td><td style="text-align:right;">call <code>run_natural_convection_2d(; Rc=10)</code> directly (not via .krk yet)</td></tr><tr><td style="text-align:right;">use an STL geometry</td><td style="text-align:right;"><code>Obstacle body stl(file=&quot;geom.stl&quot;)</code></td></tr><tr><td style="text-align:right;">sweep parameters</td><td style="text-align:right;"><code>Sweep Re = [100, 200, 400]</code></td></tr><tr><td style="text-align:right;">run from the terminal</td><td style="text-align:right;"><code>kraken run sim.krk</code> (CLI wrapper, <code>bin/kraken</code>)</td></tr></tbody></table>`,54)])])}const x=e(r,[["render",d]]);export{y as __pageData,x as default};
